# === task_a.py ===
from decimal import Decimal, InvalidOperation

CONFLICT_REASON = "payload differs from first occurrence"


def _d2_from_cents(cents):
    sign = "-" if cents < 0 else ""
    a = abs(cents)
    q, r = divmod(a, 100)
    return Decimal(f"{sign}{q}.{r:02d}")


def _to_d2_and_cents(amount):
    t = amount.as_tuple()
    if t.digits:
        int_digits = int("".join(map(str, t.digits)))
    else:
        int_digits = 0
    shift = t.exponent + 2
    if shift >= 0:
        cents = int_digits * (10 ** shift) if shift else int_digits
    else:
        # Should not happen because caller validates exponent >= -2,
        # kept for safety (would imply more than 2 decimal places).
        raise ValueError("amount must have at most 2 decimal places")
    if t.sign:
        cents = -cents
    return _d2_from_cents(cents), cents


def _parse_amount(value):
    if not isinstance(value, str):
        raise ValueError("amount must be a string")
    try:
        amount = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid amount: {value!r}") from None
    if not amount.is_finite() or amount <= 0:
        raise ValueError("amount must be finite and > 0")
    if amount.as_tuple().exponent < -2:
        raise ValueError("amount must have at most 2 decimal places")
    d2, _ = _to_d2_and_cents(amount)
    return d2


def _validate(request):
    if not isinstance(request, dict):
        raise ValueError("each request must be a dict")
    for field in ("key", "account", "currency", "amount", "reference"):
        if field not in request:
            raise ValueError(f"missing field: {field}")
    key = request["key"]
    account = request["account"]
    currency = request["currency"]
    reference = request["reference"]
    if not isinstance(key, str) or key == "":
        raise ValueError("key must be a non-empty string")
    if not isinstance(account, str) or account == "":
        raise ValueError("account must be a non-empty string")
    if (
        not isinstance(currency, str)
        or len(currency) != 3
        or not currency.isalpha()
        or not currency.isascii()
    ):
        raise ValueError("currency must be exactly 3 letters")
    if not isinstance(reference, str):
        raise ValueError("reference must be a string")
    amount = _parse_amount(request["amount"])
    return key, account, currency.upper(), amount, reference


def _cents_of_d2(d2):
    t = d2.as_tuple()
    if t.digits:
        int_digits = int("".join(map(str, t.digits)))
    else:
        int_digits = 0
    shift = t.exponent + 2
    if shift == 0:
        cents = int_digits
    elif shift > 0:
        cents = int_digits * (10 ** shift)
    else:
        raise ValueError("unexpected exponent")
    if t.sign:
        cents = -cents
    return cents


def process_payments(requests):
    if not isinstance(requests, list):
        raise ValueError("requests must be a list")
    seen = {}
    applied = []
    duplicates = []
    conflicts = []
    balances_cents = {}
    for request in requests:
        key, account, currency, amount, reference = _validate(request)
        payload = (account, currency, amount, reference)
        if key in seen:
            if seen[key] == payload:
                duplicates.append(key)
            else:
                conflicts.append({"key": key, "reason": CONFLICT_REASON})
            continue
        seen[key] = payload
        balance_key = (account, currency)
        amount_cents = _cents_of_d2(amount)
        new_cents = balances_cents.get(balance_key, 0) + amount_cents
        balances_cents[balance_key] = new_cents
        new_balance = _d2_from_cents(new_cents)
        applied.append(
            {
                "key": key,
                "account": account,
                "currency": currency,
                "amount": amount,
                "balance_after": new_balance,
            }
        )
    balances = {
        f"{account}:{currency}": _d2_from_cents(balances_cents[(account, currency)])
        for account, currency in sorted(balances_cents, key=lambda p: f"{p[0]}:{p[1]}")
    }
    return {
        "applied": applied,
        "duplicates": duplicates,
        "conflicts": conflicts,
        "balances": balances,
    }

