from decimal import Decimal, InvalidOperation
from fractions import Fraction


def _parse(value):
    if not isinstance(value, str):
        raise ValueError("input must be a string")
    try:
        number = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid decimal: {value!r}") from None
    if not number.is_finite():
        raise ValueError("input must be finite")
    return number


def _quantize_frac_to_2(frac):
    # Round exact rational frac to 2 decimal places with ROUND_HALF_UP
    # (ties away from zero) without any Decimal context precision limits.
    p = frac.numerator * 100
    q = frac.denominator
    if p >= 0:
        r = (2 * p + q) // (2 * q)
    else:
        r = -((-2 * p + q) // (2 * q))
    sign = "-" if r < 0 else ""
    ar = abs(r)
    dollars, cents = divmod(ar, 100)
    return Decimal(f"{sign}{dollars}.{cents:02d}")


def percent_change(old: str, new: str) -> Decimal | None:
    old_d, new_d = _parse(old), _parse(new)
    if old_d == 0:
        return Decimal("0.00") if new_d == 0 else None
    change = (Fraction(new_d) - Fraction(old_d)) / abs(Fraction(old_d)) * 100
    return _quantize_frac_to_2(change)


def apply_percent_change(old: str, percent: str) -> Decimal:
    old_d, pct = _parse(old), _parse(percent)
    result = Fraction(old_d) * (1 + Fraction(pct) / 100)
    return _quantize_frac_to_2(result)
